-- ---------------------------------------------------------------------------------------------
-- Least privilege (data-model §5.1). bos_owner's default privileges would hand bos_app full rights
-- on new tables, so the auth tables are revoked from it explicitly.
REVOKE ALL ON "users", "sessions", "accounts", "verifications", "rate_limits" FROM bos_app;
GRANT SELECT, INSERT, UPDATE, DELETE ON "users", "sessions", "accounts", "verifications", "rate_limits" TO bos_auth;
-- Tenant code may read only non-sensitive user columns (no email, no auth columns), under RLS.
GRANT SELECT ("id", "name", "image_url") ON "users" TO bos_app;

-- Row-Level Security: every identity table is visible to bos_auth only; FORCE applies it to the
-- table owner too. Tables without a policy for a role show that role nothing.
ALTER TABLE "users" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "users" FORCE ROW LEVEL SECURITY;
CREATE POLICY users_auth ON "users" FOR ALL TO bos_auth USING (true) WITH CHECK (true);
-- Tenant code sees the current user only. The tenancy migration widens this to members of the
-- current business (data-model §5.6) once memberships exist.
CREATE POLICY users_visible_to_app ON "users" FOR SELECT TO bos_app
  USING ("id" = nullif(current_setting('app.user_id', true), '')::uuid);

ALTER TABLE "sessions" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "sessions" FORCE ROW LEVEL SECURITY;
CREATE POLICY sessions_auth ON "sessions" FOR ALL TO bos_auth USING (true) WITH CHECK (true);

ALTER TABLE "accounts" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "accounts" FORCE ROW LEVEL SECURITY;
CREATE POLICY accounts_auth ON "accounts" FOR ALL TO bos_auth USING (true) WITH CHECK (true);

ALTER TABLE "verifications" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "verifications" FORCE ROW LEVEL SECURITY;
CREATE POLICY verifications_auth ON "verifications" FOR ALL TO bos_auth USING (true) WITH CHECK (true);

ALTER TABLE "rate_limits" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "rate_limits" FORCE ROW LEVEL SECURITY;
CREATE POLICY rate_limits_auth ON "rate_limits" FOR ALL TO bos_auth USING (true) WITH CHECK (true);

-- A stored session hash is exactly hex(sha256(token)), so the database can verify a session token
-- itself (app_private.session_user_id, added with the tenancy functions).
ALTER TABLE "sessions" ADD CONSTRAINT sessions_token_hash_format CHECK ("token_hash" ~ '^[0-9a-f]{64}$');
